use Civi\Lughauth\Features\Document\TemplateVersion\Application\Usecase\Retrieve\TemplateVersionRetrieveAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class IsAuthenticatedRetrieveAllow
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function __invoke(TemplateVersionRetrieveAllowDecision $proposal): TemplateVersionRetrieveAllowDecision
    {
        $this->logDebug("Check IsAuthenticatedRetrieveAllow Template version");
        $span = $this->startSpan("Check IsAuthenticatedRetrieveAllow Template version");
        try {
            $userContext = $this->context->getIdentity();
            if ($proposal->isAllowed()) {
                if (! !$userContext->anonymous) {
                    $proposal->deny('Disabled if not IsAuthenticatedRetrieve');
